.thread{max-width:820px;margin:0 auto;padding:28px 20px 12px;display:flex;flex-direction:column;gap:26px;min-height:100%}
.u{display:flex;justify-content:flex-end}
.u .b{max-width:75%;background:#1b3247;border-radius:18px;padding:10px 16px;line-height:1.5;white-space:pre-wrap;word-wrap:break-word}
