// Ask UBM chat, laid out like ChatGPT: one scrolling thread in a centred
// column, and the composer pinned under it. Everything shown comes from the
// model (the page store); the widget only sends events out: onAsk,
// onPickCustomer, onClear, onDownloadChart. Charts are drawn with ECharts
// (loaded in the html) from the result rows; the AI only names the columns.
var SUGGEST = [
  ["Cost by month", "Show total cost by month for the last 12 months"],
  ["Top electric users", "Find the top 5 locations by electric usage last year"],
  ["Vendors", "Total cost by vendor this year"],
  ["Year over year", "Compare electricity usage this year vs last year by month"]
];
var ROWS_COLLAPSED = 10;
// Answer mark: a lightning bolt for an energy app, not any AI vendor's logo.
var MARK = '<div class="av"><svg viewBox="0 0 24 24" width="15" height="15"><path d="M13 2 4.5 13.5H11L10 22l8.5-11.5H12L13 2z" fill="currentColor"/></svg></div>';
var COLORS = ["#4c9aff", "#f2c94c", "#6fcf97", "#bb6bd9", "#f2994a", "#56ccf2", "#eb5757", "#a0b4c8"];
var M = {};
var expanded = {};
var view = {};      // per answer: "chart" or "table"
var charts = {};    // live ECharts instances by answer index
var animated = {};  // answers whose chart has already animated in
var lastCount = -1;

var root = document.getElementById("root");
root.innerHTML =
  '<div class="app">' +
  '<div class="top"><span class="title">Ask UBM</span>' +
  '<select id="cust" class="cust" title="Customer"></select>' +
  '<span class="facts" id="facts"></span><span class="spacer"></span>' +
  '<button class="newchat" id="clear" title="Start a new chat">' +
  '<svg viewBox="0 0 24 24" width="16" height="16"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" fill="none"/></svg>New chat</button></div>' +
  '<div class="scroll" id="scroll"><div class="thread" id="thread"></div></div>' +
  '<div class="dock"><div class="composer" id="composer">' +
  '<textarea id="q" rows="1" placeholder="Ask about this customer\'s usage and cost"></textarea>' +
  '<button class="send" id="send" title="Send" disabled>' +
  '<svg viewBox="0 0 24 24" width="18" height="18"><path d="M12 19V5M5 12l7-7 7 7" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></button>' +
  '</div><div class="hint">Answers are based on this customer\'s monthly usage and cost data.</div></div>' +
  '</div>';

var $ = function (id) { return document.getElementById(id); };

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}

function isNum(v) {
  return typeof v === "number" || (typeof v === "string" && /^-?\d+(\.\d+)?$/.test(v) && v.length < 16);
}

function fmt(v) {
  if (v == null || v === "") return '<span class="muted">—</span>';
  if (isNum(v)) return Number(v).toLocaleString(undefined, { maximumFractionDigits: 2 });
  if (typeof v === "object") return esc(JSON.stringify(v));
  return esc(v);
}

function label(c) {
  var s = String(c).replace(/_/g, " ");
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function table(m, i) {
  if (!m.columns || !m.columns.length) return "";
  var all = m.rows || [];
  var open = !!expanded[i];
  var shown = open ? all : all.slice(0, ROWS_COLLAPSED);
  var h = '<div class="tbl"><table><thead><tr>' +
    m.columns.map(function (c) { return "<th>" + esc(label(c)) + "</th>"; }).join("") + "</tr></thead><tbody>";
  shown.forEach(function (r) {
    h += "<tr>" + m.columns.map(function (c) {
      return '<td class="' + (isNum(r[c]) ? "n" : "") + '">' + fmt(r[c]) + "</td>";
    }).join("") + "</tr>";
  });
  h += "</tbody></table></div>";
  var foot = '<div class="tfoot"><span>' + m.rowCount + (m.rowCount === 1 ? " row" : " rows") +
    (m.rowCount > all.length ? " (first " + all.length + " kept)" : "") + "</span>";
  if (all.length > ROWS_COLLAPSED) {
    foot += '<button class="more" data-i="' + i + '">' + (open ? "Show fewer" : "Show all " + all.length + " rows") + "</button>";
  }
  return h + foot + "</div>";
}

function canChart(m) {
  return !!(m.chart && typeof echarts !== "undefined" && (m.rows || []).length > 1);
}

function result(m, i) {
  if (!m.columns || !m.columns.length) return "";
  if (!canChart(m)) return table(m, i);
  var v = view[i] || "chart";
  var bar = '<div class="rbar"><span class="rtitle">' + esc(m.chart.title || "") + "</span>" +
    '<span class="seg"><button class="' + (v === "chart" ? "on" : "") + '" data-v="chart" data-i="' + i + '">Chart</button>' +
    '<button class="' + (v === "table" ? "on" : "") + '" data-v="table" data-i="' + i + '">Table</button></span>' +
    (v === "chart" ? '<button class="dl" data-i="' + i + '" title="Download chart as PNG">' +
      '<svg viewBox="0 0 24 24" width="15" height="15"><path d="M12 4v11M7 10l5 5 5-5M5 20h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></button>' : "") +
    "</div>";
  return bar + (v === "chart" ? '<div class="chart" data-i="' + i + '"></div>' : table(m, i));
}

function shortLabel(v) {
  var s = v == null ? "" : String(v);
  return /^\d{4}-\d{2}-\d{2}/.test(s) ? s.slice(0, 7) : s;
}

function chartOption(m, animate) {
  var c = m.chart, rows = m.rows || [];
  var cats = [], seen = {};
  rows.forEach(function (r) {
    var k = shortLabel(r[c.x]);
    if (!seen[k]) { seen[k] = 1; cats.push(k); }
  });
  var series = [];
  if (c.series) {
    var groups = {}, order = [];
    rows.forEach(function (r) {
      var g = r[c.series] == null ? "—" : String(r[c.series]);
      if (!groups[g]) { groups[g] = {}; order.push(g); }
      groups[g][shortLabel(r[c.x])] = r[c.y[0]];
    });
    order.forEach(function (g) {
      series.push({ name: g, data: cats.map(function (k) { return groups[g][k] == null ? null : Number(groups[g][k]); }) });
    });
  } else {
    c.y.forEach(function (col) {
      var byCat = {};
      rows.forEach(function (r) { byCat[shortLabel(r[c.x])] = r[col]; });
      series.push({ name: label(col), data: cats.map(function (k) { return byCat[k] == null ? null : Number(byCat[k]); }) });
    });
  }
  series.forEach(function (s) {
    s.type = c.type;
    if (c.type === "bar") { s.barMaxWidth = 42; s.itemStyle = { borderRadius: [4, 4, 0, 0] }; }
    else { s.smooth = true; s.symbolSize = 6; s.connectNulls = false; }
  });
  var num = function (v) { return v == null ? "—" : Number(v).toLocaleString(undefined, { maximumFractionDigits: 2 }); };
  var many = cats.length > 8;
  return {
    animation: !!animate,
    color: COLORS,
    backgroundColor: "transparent",
    textStyle: { color: "#8ea3b5", fontFamily: "inherit" },
    grid: { left: 12, right: 18, top: series.length > 1 ? 40 : 24, bottom: 8, containLabel: true },
    legend: series.length > 1 ? { top: 0, textStyle: { color: "#c5d3df" }, icon: "roundRect", itemWidth: 12, itemHeight: 8 } : undefined,
    tooltip: { trigger: "axis", backgroundColor: "#132230", borderColor: "#2a4258", textStyle: { color: "#e7eef4" },
      valueFormatter: function (v) { return (c.y_label === "$" ? "$" : "") + num(v) + (c.y_label && c.y_label !== "$" ? " " + c.y_label : ""); } },
    xAxis: { type: "category", data: cats, axisLine: { lineStyle: { color: "#2a4258" } }, axisTick: { show: false },
      axisLabel: { color: "#8ea3b5", interval: 0, rotate: many ? 35 : 0, hideOverlap: true,
        formatter: function (s) { return s.length > 18 ? s.slice(0, 17) + "…" : s; } } },
    yAxis: { type: "value", name: c.y_label || "", nameTextStyle: { color: "#6f8699", align: "left" },
      splitLine: { lineStyle: { color: "#1a2c3d" } },
      axisLabel: { color: "#8ea3b5", formatter: function (v) {
        var a = Math.abs(v);
        var s = a >= 1e9 ? (v / 1e9).toFixed(1) + "B" : a >= 1e6 ? (v / 1e6).toFixed(1) + "M" : a >= 1e3 ? (v / 1e3).toFixed(0) + "K" : String(v);
        return (c.y_label === "$" ? "$" : "") + s;
      } } },
    series: series
  };
}

// The thread is rebuilt on every model change, so charts are recreated each
// time; only a chart's first appearance animates.
function drawCharts() {
  Object.keys(charts).forEach(function (k) { charts[k].dispose(); });
  charts = {};
  if (typeof echarts === "undefined") return;
  var msgs = M.messages || [];
  Array.prototype.forEach.call(document.querySelectorAll(".chart[data-i]"), function (el) {
    var i = el.getAttribute("data-i");
    var m = msgs[i];
    if (!m || !m.chart) return;
    var inst = echarts.init(el, null, { renderer: "canvas" });
    inst.setOption(chartOption(m, !animated[i]));
    animated[i] = true;
    charts[i] = inst;
  });
}

function downloadChart(i) {
  var inst = charts[i], m = (M.messages || [])[i];
  if (!inst || !m) return;
  var url = inst.getDataURL({ type: "png", pixelRatio: 2, backgroundColor: "#0d1822" });
  var name = String((m.chart && m.chart.title) || "chart").replace(/[^\w\- ]+/g, "").trim().replace(/\s+/g, "-").toLowerCase() || "chart";
  // The iframe cannot save files itself; the page's download() does it.
  appsmith.triggerEvent("onDownloadChart", { fileData: url, fileName: name + ".png" });
}

function custName() {
  var want = String(M.customer || "");
  var c = (M.customers || []).filter(function (x) { return String(x.id) === want; })[0];
  return c ? c.name : "this customer";
}

function renderTop() {
  var sel = $("cust");
  var list = M.customers || [];
  var want = String(M.customer || "");
  var html = list.map(function (c) {
    return '<option value="' + esc(c.id) + '"' + (String(c.id) === want ? " selected" : "") + ">" + esc(c.name) + "</option>";
  }).join("");
  if (!list.length) html = '<option value="' + esc(want) + '">' + (want ? "Customer " + esc(want) : "Loading…") + "</option>";
  if (sel.innerHTML !== html) sel.innerHTML = html;
  var f = M.facts || {};
  $("facts").textContent = f.first_month ? f.first_month + " – " + f.last_month + " · " + f.locations + " locations" : "";
}

function renderThread() {
  var msgs = M.messages || [];
  var h = "";
  if (!msgs.length && !M.busy) {
    var f = M.facts || {};
    h += '<div class="empty"><h2>What would you like to know?</h2>' +
      '<p>Ask about ' + esc(custName()) + "'s usage and cost" +
      (f.utilities ? " (" + esc(f.utilities) + ")" : "") + ".</p><div class=\"cards\">" +
      SUGGEST.map(function (s) {
        return '<button class="card" data-q="' + esc(s[1]) + '"><b>' + esc(s[0]) + "</b><span>" + esc(s[1]) + "</span></button>";
      }).join("") + "</div></div>";
  }
  msgs.forEach(function (m, i) {
    if (m.role === "user") {
      h += '<div class="u"><div class="b">' + esc(m.text) + "</div></div>";
      return;
    }
    h += '<div class="a">' + MARK + '<div class="body">' +
      '<div class="answer">' + esc(m.text).replace(/\n/g, "<br>") + "</div>" +
      (m.error ? '<div class="err">' + esc(m.error) + "</div>" : "") +
      result(m, i) + "</div></div>";
  });
  if (M.busy) {
    h += '<div class="a">' + MARK + '<div class="body"><div class="busy">' +
      '<span class="dots"><i></i><i></i><i></i></span>' + esc(M.busy) + "</div></div></div>";
  }
  $("thread").innerHTML = h;
  drawCharts();
  var count = msgs.length + (M.busy ? 0.5 : 0);
  if (count !== lastCount) {
    var sc = $("scroll");
    sc.scrollTop = sc.scrollHeight;
    lastCount = count;
  }
}

function syncSend() {
  $("send").disabled = !!M.busy || !$("q").value.trim();
}

function render(model) {
  M = model || {};
  renderTop();
  renderThread();
  syncSend();
}

function grow() {
  var t = $("q");
  t.style.height = "auto";
  t.style.height = Math.min(t.scrollHeight, 200) + "px";
}

function send(text) {
  var q = String(text == null ? $("q").value : text).trim();
  if (!q || M.busy) return;
  $("q").value = "";
  grow();
  syncSend();
  appsmith.triggerEvent("onAsk", { question: q });
}

$("send").addEventListener("click", function () { send(); });
$("q").addEventListener("input", function () { grow(); syncSend(); });
$("q").addEventListener("keydown", function (e) {
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
});
$("composer").addEventListener("click", function () { $("q").focus(); });
$("clear").addEventListener("click", function () { expanded = {}; view = {}; animated = {}; appsmith.triggerEvent("onClear", {}); });
$("cust").addEventListener("change", function (e) {
  expanded = {}; view = {}; animated = {};
  appsmith.triggerEvent("onPickCustomer", { pickedCustomer: e.target.value });
});
$("thread").addEventListener("click", function (e) {
  var card = e.target.closest(".card");
  if (card) { send(card.getAttribute("data-q")); return; }
  var seg = e.target.closest(".seg button");
  if (seg) { view[seg.getAttribute("data-i")] = seg.getAttribute("data-v"); renderThread(); return; }
  var dl = e.target.closest(".dl");
  if (dl) { downloadChart(dl.getAttribute("data-i")); return; }
  var more = e.target.closest(".more");
  if (more) {
    var i = more.getAttribute("data-i");
    expanded[i] = !expanded[i];
    renderThread();
  }
});

// ---- fit to the browser window --------------------------------------------
// Appsmith sizes this widget by its content (auto height) and has no way to
// size it to the window, and the iframe cannot read the window size. An
// IntersectionObserver can still see how much of the iframe is on screen, so:
// grow tall, measure the visible part, then shrink to exactly that. The page
// then has nothing to scroll and the thread is the only scrollbar.
var MIN_H = 420, PROBE_H = 2400, FALLBACK_H = 700;
var fitted = false, lastW = window.innerWidth, fallbackTimer = null;

function setH(h) {
  root.style.height = Math.round(h) + "px";
  var sc = $("scroll");
  if (sc) sc.scrollTop = sc.scrollHeight;
}

function probe() {
  fitted = false;
  setH(PROBE_H);
  clearTimeout(fallbackTimer);
  fallbackTimer = setTimeout(function () { if (!fitted) { fitted = true; setH(FALLBACK_H); } }, 4000);
}

var steps = [];
for (var s = 0; s <= 200; s++) steps.push(s / 200);
new IntersectionObserver(function (entries) {
  if (fitted) return;
  var r = entries[entries.length - 1].intersectionRect;
  // Measure only once Appsmith has grown the iframe past the visible area
  // (otherwise the clip is the iframe's own edge) and its top is on screen.
  if (r.height < 50 || r.top > 2 || window.innerHeight < r.height + 20) return;
  fitted = true;
  clearTimeout(fallbackTimer);
  setH(Math.max(MIN_H, r.height - 6));
}, { threshold: steps }).observe(root);

// A width change means the browser window was resized: fit again. (Height
// changes also come from Appsmith resizing the iframe to match, so ignore them.)
window.addEventListener("resize", function () {
  if (Math.abs(window.innerWidth - lastW) < 2) return;
  lastW = window.innerWidth;
  probe();
});
probe();

window.addEventListener("resize", function () {
  Object.keys(charts).forEach(function (k) { charts[k].resize(); });
});

appsmith.onReady(function () {
  render(appsmith.model);
  appsmith.onModelChange(function (m) { render(m); });
});
